    print('  Non-empty columns:', min(nonempty_cols), get_column_letter(min(nonempty_cols)), 'through', max(nonempty_cols), get_column_letter(max(nonempty_cols)))
else:
    print('  No non-empty cells found')
# print rows with A:L or all nonempty condensed
for r in range(21,39):
    entries=[]
    for c in sorted(nonempty_cols):
        v=wd.cell(r,c).value
        if v is not None:
            entries.append(f'{get_column_letter(c)}={v!r}')
    print(f'  row {r}: ' + '; '.join(entries))

# detect exact layout: header row years, code col, data extent
print('\nDetected Data layout candidates:')
for r in range(21,39):
    years=[]
    for c in range(1, wd.max_column+1):
        v=wd.cell(r,c).value
        if isinstance(v, int) and 1900 <= v <= 2100 or isinstance(v, str) and v.strip().isdigit() and 1900 <= int(v.strip()) <= 2100:
            years.append((c,v))
    if years:
        print(f'  row {r} year-like headers:', [(get_column_letter(c),v) for c,v in years])
for c in range(1, min(wd.max_column,10)+1):
    vals=[wd.cell(r,c).value for r in range(22,39) if wd.cell(r,c).value is not None]
