from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
outfile='/root/output/result.xlsx'
wb=load_workbook(outfile, data_only=False)
ws=wb['Task']
print('Reopened:', outfile)
print('Sheets:', wb.sheetnames)
errors=[]
expected_ranges=[]
for start,end in [(12,17),(19,24),(26,31),(35,40),(42,47)]:
    for r in range(start,end+1):
        for c in range(8,13):
            expected_ranges.append((r,c))
for c in range(8,13):
    expected_ranges.append((50,c))
for r,c in expected_ranges:
    v=ws.cell(r,c).value
    addr=f'{get_column_letter(c)}{r}'
    if not (isinstance(v,str) and v.startswith('=')):
        errors.append(f'{addr} expected formula, found {v!r}')

# More specific checks for correct references/ranges.
lookup_cells=[]
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            lookup_cells.append((r,c))
for r,c in lookup_cells:
    v=ws.cell(r,c).value
    col=get_column_letter(c)
    expected=f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))'
    if v != expected:
        errors.append(f'{col}{r} lookup mismatch: {v!r} != {expected!r}')

for r in range(35,41):
    for c in range(8,13):
        col=get_column_letter(c)
        inbound=12+(r-35); outbound=19+(r-35); capacity=26+(r-35)
        expected=f'=({col}{inbound}-{col}{outbound})/{col}{capacity}*100'
        v=ws.cell(r,c).value
        if v != expected:
            errors.append(f'{col}{r} net flow mismatch: {v!r} != {expected!r}')

for c in range(8,13):
    col=get_column_letter(c)
    expected_by_row={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40, 0.25)',
        47:f'=PERCENTILE({col}35:{col}40, 0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r, expected in expected_by_row.items():
        v=ws.cell(r,c).value
        if v != expected:
            errors.append(f'{col}{r} stat/weighted mismatch: {v!r} != {expected!r}')

print('\nFormula cell count checked:', len(expected_ranges))
print('Empty/non-formula errors:', sum('expected formula' in e for e in errors))
print('Total verification errors:', len(errors))
print('\nSample formulas:')
samples=['H12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']
for addr in samples:
    print(f'  {addr}: {ws[addr].value}')
if errors:
    print('\nERRORS:')
    for e in errors[:50]:
        print('  ' + e)
    raise SystemExit(1)
print('\nVerification passed: all target cells contain expected formulas and references.')
